css:
.stack {
  display: grid;
  gap: 12px;
  justify-items: start;
  padding: 24px;
  font-family: system-ui, sans-serif;
  font-size: 17px;
}

.required::after {
  content: " *";
  color: #dc2626;
  font-weight: 700;
}

.links {
  margin: 0;
}

.links a {
  color: #c2410c;
}

.external::after {
  content: " ↗";
  font-size: 0.8em;
}

.quote {
  margin: 0;
  font-style: italic;
}

.quote::before {
  content: "“";
  color: #f97316;
}

.quote::after {
  content: "”";
  color: #f97316;
}
